const collectionNames={learned:'Изученные',due:'К повторению',favorite:'Избранное'};
const collectionDescriptions={learned:'Слова, которые ты уже знаешь. Они продолжат появляться в повторении.',due:'Карточки, которые пора повторить. Просмотр не меняет расписание.',favorite:'Сохранённые слова. Открой карточку или убери из избранного.'};
function collectionItems(which){return words.filter(w=>{let s=state[w[1]];return !!s&&(which==='learned'?s.n>=3:which==='due'?s.due>0&&s.due<=Date.now()&&!hiddenDue.has(w[1]):s.fav)})}
function setCollection(which){let wasOpen=!!collection;if(!wasOpen&&which)collectionReturnFocus=document.activeElement;collection=collection===which?null:which;collectionDisplayLimit=36;$('collection-drawer').scrollTop=0;renderCollectionDrawer();if(collection)requestAnimationFrame(()=>$('collection-drawer').focus({preventScroll:true}));}
