function normalize(s){return s.toLowerCase().normalize('NFKC').replace(/[’‘]/g,"'").replace(/\b(can't)\b/g,'cannot').replace(/\b(won't)\b/g,'will not').replace(/\b(\w+)n't\b/g,'$1 not').replace(/\b(i'm)\b/g,'i am').replace(/\b(you|we|they)'re\b/g,'$1 are').replace(/\b(i|you|we|they)'ve\b/g,'$1 have').replace(/\b(i|you|he|she|it|we|they)'ll\b/g,'$1 will').replace(/\b(he|she|it)'s\s+(?=not\b)/g,'$1 is ').replace(/[.,!?;:…“”"]/g,'').trim().replace(/\s+/g,' ')}
