const englishIdioms=[["break the ice","разрядить обстановку","Когда вы знакомитесь с людьми или начинаете разговор в напряжённой компании и хотите, чтобы всем стало проще общаться.","He told a joke to break the ice.","Он рассказал шутку, чтобы разрядить обстановку."],["a piece of cake","проще простого","Когда задание, которое могло показаться трудным, оказалось настолько лёгким, что вы справились без особых усилий. Разговорное выражение.","The exam was a piece of cake.","Экзамен был проще простого."],["once in a blue moon","крайне редко","Когда рассказываете о привычке или событии, которое бывает исключительно редко, а не просто время от времени.","We eat out once in a blue moon.","Мы крайне редко едим в ресторанах."],["spill the beans","выдать секрет","Когда кто-то раскрывает секрет или вы просите человека рассказать то, что он до сих пор скрывал. Разговорное выражение.","Don't spill the beans about the party.","Не выдавай секрет о вечеринке."],["under the weather","плохо себя чувствовать","Когда вы слегка заболели, чувствуете слабость или недомогание и не хотите подробно объяснять своё состояние.","I'm feeling under the weather today.","Сегодня я неважно себя чувствую."],["hit the nail on the head","попасть в точку","Когда собеседник очень точно описал проблему, угадал её причину или выразил именно ту мысль, которую вы имели в виду.","You hit the nail on the head with that comment.","Своим замечанием ты попал в точку."],["cost an arm and a leg","стоить целое состояние","Когда обсуждаете покупку, цену которой считаете чрезвычайно высокой. Часто употребляется с преувеличением.","That jacket costs an arm and a leg.","Эта куртка стоит целое состояние."],["let the cat out of the bag","проговориться","Когда кто-то раньше времени раскрыл тайну, например выдал готовящийся сюрприз, который должен был оставаться секретом.","She let the cat out of the bag about the surprise.","Она проговорилась о сюрпризе."],["bite the bullet","решиться на неприятное","Когда долго откладывали неприятное, но необходимое дело и наконец готовы на него решиться.","I finally bit the bullet and went to the dentist.","Я наконец собрался с духом и пошёл к стоматологу."],["on the same page","одинаково понимать ситуацию","Когда обсуждаете совместную работу или планы и хотите убедиться, что все участники одинаково понимают задачу.","Let's make sure we're on the same page.","Давай убедимся, что мы одинаково понимаем ситуацию."],["in hot water","в неприятностях","Когда человек нарушил правила, допустил ошибку и теперь рискует столкнуться с неприятностями или недовольством окружающих.","He got into hot water for missing the deadline.","Он попал в неприятности из-за того, что не уложился в срок."],["beat around the bush","ходить вокруг да около","Когда собеседник долго говорит намёками, избегая главного, а вам хочется, чтобы он перешёл прямо к сути.","Stop beating around the bush and tell me the truth.","Хватит ходить вокруг да около, скажи правду."],["call it a day","закончить на сегодня","Когда рабочий день или занятие можно закончить, потому что на сегодня сделано достаточно или продолжать уже нет смысла.","We've done enough. Let's call it a day.","Мы достаточно поработали. Давай на сегодня закончим."],["get cold feet","струсить в последний момент","Когда человек собирался сделать что-то важное, но непосредственно перед этим испугался и начал сомневаться.","He got cold feet before the interview.","Перед собеседованием он струсил."],["keep an eye on","присматривать за","Когда просите кого-то временно присмотреть за вещью, ребёнком или питомцем либо следить за изменениями ситуации.","Could you keep an eye on my bag?","Можешь присмотреть за моей сумкой?"],["out of the blue","совершенно неожиданно; как гром среди ясного неба","Когда произошло нечто совершенно неожиданное, чего вы не могли предвидеть: новость, звонок или внезапная встреча.","She called me out of the blue.","Она позвонила мне совершенно неожиданно."],["pull someone's leg","подшучивать над кем-либо","Когда хотите сказать собеседнику, что его разыгрывают и не стоит воспринимать сказанное всерьёз.","Relax, I'm just pulling your leg.","Расслабься, я просто над тобой подшучиваю."],["the last straw","последняя капля","Когда после нескольких неприятностей происходит ещё одна, пусть даже небольшая, и терпеть дальше уже невозможно.","That rude remark was the last straw.","Это грубое замечание стало последней каплей."],["go the extra mile","сделать больше, чем требуется","Когда хотите похвалить человека за то, что он приложил больше усилий, чем от него ожидали.","She always goes the extra mile for her customers.","Она всегда делает для клиентов больше, чем от неё требуется."],["throw in the towel","сдаться","Когда кто-то перестаёт бороться с трудной задачей и признаёт поражение либо вы убеждаете его не сдаваться.","Don't throw in the towel just yet.","Пока не сдавайся."],["a blessing in disguise","нет худа без добра","Когда неприятное на первый взгляд событие неожиданно привело к чему-то хорошему и вы осознали это позже.","Losing that job was a blessing in disguise.","Потеря той работы в итоге обернулась благом."],["burn the midnight oil","работать допоздна","Когда рассказываете, что учились или работали далеко за полночь ради срока, экзамена или другой задачи.","I burned the midnight oil to finish the report.","Я работал допоздна, чтобы закончить отчёт."],["cut corners","экономить в ущерб качеству","Когда кто-то экономит время или деньги, пропуская важные этапы работы и рискуя качеством или безопасностью.","Never cut corners on safety.","Никогда не экономь в ущерб безопасности."],["face the music","отвечать за последствия","Когда человеку больше не удаётся избегать ответственности и приходится принять неприятные последствия своего поступка.","He had to face the music after lying.","Ему пришлось отвечать за последствия своей лжи."],["get out of hand","выйти из-под контроля","Когда ссора, расходы, поведение или другая ситуация перестают поддаваться контролю и начинают ухудшаться.","The argument quickly got out of hand.","Спор быстро вышел из-под контроля."],["give someone the benefit of the doubt","трактовать сомнения в пользу человека; поверить ему, пока нет доказательств обратного","Когда не уверены в чьей-то неправоте и предпочитаете допустить, что человек мог поступить честно, пока нет убедительных доказательств обратного.","I'll give her the benefit of the doubt.","Пока я предпочту ей поверить."],["hang in there","держись","Когда хотите по-дружески поддержать человека, которому сейчас трудно, и помочь ему не сдаваться.","Hang in there. Things will get better.","Держись. Всё наладится."],["in the same boat","в одной лодке","Когда у вас и собеседника одинаковые трудности или общая проблема и вы хотите подчеркнуть, что он в этом не один.","We're all in the same boat.","Мы все в одной лодке."],["keep one's fingers crossed","держать кулачки","Когда ждёте результатов экзамена, собеседования или другого важного события и надеетесь на удачный исход для себя или другого человека.","I'll keep my fingers crossed for you.","Буду держать за тебя кулачки."],["kill two birds with one stone","убить двух зайцев одним выстрелом","Когда одно действие одновременно решает две разные задачи и позволяет сэкономить время или усилия.","Cycling to work kills two birds with one stone.","Поездка на работу на велосипеде позволяет убить двух зайцев одним выстрелом."],["leave no stone unturned","перепробовать всё","Когда хотите подчеркнуть, что при поиске решения, человека или информации были использованы все доступные способы.","They left no stone unturned in their search.","В поисках они перепробовали всё возможное."],["make ends meet","сводить концы с концами","Когда обсуждаете ограниченный доход, которого едва хватает на жильё, еду и другие необходимые расходы.","It's hard to make ends meet on that salary.","На такую зарплату трудно сводить концы с концами."],["miss the boat","упустить возможность","Когда важный срок или удобный момент уже прошёл и человек из-за промедления лишился возможности.","Apply now or you'll miss the boat.","Подай заявку сейчас, иначе упустишь возможность."],["not one's cup of tea","не по душе","Когда хотите вежливо и не слишком резко сказать, что какое-то занятие, фильм или стиль вам не нравится.","Horror films aren't my cup of tea.","Фильмы ужасов мне не по душе."],["on cloud nine","на седьмом небе от счастья","Когда получили очень радостную новость, добились важной цели или переживаете момент необыкновенного счастья.","She was on cloud nine after passing her exam.","Она была на седьмом небе от счастья после сдачи экзамена."],["play it by ear","действовать по обстоятельствам","Когда точный план заранее не нужен или обстоятельства непредсказуемы, поэтому вы решили действовать по ситуации.","We don't have a plan, so let's play it by ear.","У нас нет плана, так что будем действовать по обстоятельствам."],["put all your eggs in one basket","поставить всё на одну карту","Когда хотите предостеречь от вложения всех денег, сил или надежд в один вариант, от которого зависит весь результат.","Don't put all your eggs in one basket.","Не ставь всё на одну карту."],["rain cats and dogs","лить как из ведра","Когда на улице идёт настолько сильный дождь, что хочется подчеркнуть его интенсивность. Разговорное, довольно образное выражение.","It's raining cats and dogs outside.","На улице льёт как из ведра."],["read between the lines","читать между строк","Когда в сообщении или разговоре есть намёки, по которым нужно догадаться о невысказанных прямо намерениях.","Read between the lines of his message.","Постарайся понять скрытый смысл его сообщения."],["see eye to eye","сходиться во взглядах","Когда обсуждаете, насколько вы согласны с другим человеком по важному вопросу или одинаково оцениваете ситуацию.","We don't always see eye to eye.","Мы не всегда сходимся во взглядах."],["sit on the fence","не занимать ни одну из сторон; воздерживаться от выбора","Когда человек не хочет выбирать сторону в споре или принимать решение, хотя от него ждут определённой позиции.","He sat on the fence during the debate.","Во время спора он не встал ни на одну из сторон."],["take it with a grain of salt","относиться скептически","Когда слышите сомнительную новость, обещание или слух и советуете не доверять этому без проверки.","Take those rumours with a grain of salt.","Отнесись к этим слухам скептически."],["the ball is in your court","теперь твой ход","Когда уже сделали всё, что зависело от вас, и теперь ждёте решения или ответа другого человека.","I've made my offer. The ball is in your court.","Я сделал предложение. Теперь твой ход."],["through thick and thin","и в горе, и в радости","Когда хотите подчеркнуть преданность и поддержку людей, остающихся вместе и в благополучные, и в трудные времена.","They stayed together through thick and thin.","Они оставались вместе и в горе, и в радости."],["turn a blind eye","закрывать глаза на что-либо","Когда человек сознательно игнорирует нарушение, несправедливость или проблему, хотя знает о ней.","We can't turn a blind eye to this problem.","Мы не можем закрывать глаза на эту проблему."],["up in the air","пока не решено","Когда дата, решение, поездка или другой план ещё не подтверждены и окончательного ответа пока нет.","Our travel plans are still up in the air.","Наши планы поездки пока не определены."],["walk on eggshells","вести себя крайне осторожно","Когда рядом с человеком приходится тщательно выбирать слова и действия из опасения спровоцировать его гнев или обиду.","I feel like I'm walking on eggshells around him.","Рядом с ним мне приходится вести себя крайне осторожно."],["wrap one's head around","осмыслить, понять","Когда сталкиваетесь со сложной идеей, неожиданной новостью или фактом, который трудно понять или принять.","I can't wrap my head around this idea.","Я никак не могу осмыслить эту идею."],["your guess is as good as mine","я знаю не больше тебя","Когда вас спрашивают о чём-то неизвестном и вы хотите сказать, что не располагаете большей информацией, чем собеседник.","When will it arrive? Your guess is as good as mine.","Когда это прибудет? Я знаю не больше тебя."],["a drop in the ocean","капля в море","Когда чья-то помощь, сумма денег или усилия слишком малы по сравнению с масштабом потребности. Особенно распространено в британском английском.","This donation is a drop in the ocean compared to what's needed.","Это пожертвование — капля в море по сравнению с необходимой суммой."],["a fish out of water","не в своей тарелке","Когда оказались среди незнакомых людей или в непривычной среде и чувствуете себя неуместно.","I felt like a fish out of water at the party.","На вечеринке я чувствовал себя не в своей тарелке."],["a leopard can't change its spots","люди не меняются","Когда сомневаетесь, что человек действительно изменит давно сложившиеся привычки или черты характера. Пословица, может звучать категорично.","He promised to change, but a leopard can't change its spots.","Он обещал измениться, но характер так просто не меняется."],["a penny for your thoughts","о чём ты задумался?","Когда собеседник замолчал или задумался и вы хотите мягко узнать, о чём он думает.","You've been quiet. A penny for your thoughts?","Ты молчишь. О чём задумался?"],["a taste of one's own medicine","получить по заслугам тем же способом","Когда человек, который плохо обращался с другими, сам столкнулся с таким же отношением и ощутил его на себе.","He finally got a taste of his own medicine.","Наконец он испытал на себе то, что делал другим."],["add fuel to the fire","подливать масла в огонь","Когда слова или поступки не успокаивают конфликт, а делают уже напряжённую ситуацию ещё хуже.","His comments only added fuel to the fire.","Его замечания лишь подлили масла в огонь."],["at the drop of a hat","без колебаний, сразу","Когда хотите подчеркнуть, что кто-то готов помочь, уйти или взяться за дело сразу, без долгих раздумий.","She'd help you at the drop of a hat.","Она помогла бы тебе без малейших колебаний."],["back to square one","вернуться к исходной точке","Когда прежние усилия не привели к результату и теперь приходится начинать заново практически с нуля.","The plan failed, so we're back to square one.","План провалился, и мы вернулись к исходной точке."],["bark up the wrong tree","ошибаться в своих подозрениях; искать причину не там","Когда человек обвиняет не того, ищет решение не в том месте или основывает рассуждение на неверной причине.","If you think I took it, you're barking up the wrong tree.","Если думаешь, что это взял я, ты ошибаешься адресом."],["bend over backwards","из кожи вон лезть","Когда кто-то делает всё возможное, даже жертвуя собственным удобством, чтобы помочь или угодить другому.","They bent over backwards to help us.","Они из кожи вон лезли, чтобы нам помочь."],["bite off more than you can chew","взять на себя слишком много","Когда человек принял слишком много обязательств или взялся за задачу, с которой ему трудно справиться.","I think I've bitten off more than I can chew.","Кажется, я взял на себя слишком много."],["break a leg","ни пуха ни пера","Когда желаете удачи актёру, музыканту или другому человеку перед выступлением. Это не буквальное пожелание травмы.","Break a leg at your audition!","Ни пуха ни пера на прослушивании!"],["by the skin of one's teeth","еле-еле","Когда едва успели на транспорт, сдали экзамен с минимальным запасом или чудом избежали неудачи.","I passed the test by the skin of my teeth.","Я еле-еле сдал тест."],["caught red-handed","пойман с поличным","Когда человека обнаружили прямо во время кражи, обмана или другого проступка, а не лишь заподозрили после него.","The thief was caught red-handed.","Вора поймали с поличным."],["cross that bridge when you come to it","решать проблемы по мере поступления","Когда кто-то тревожится о возможных будущих проблемах, а вы предлагаете заняться ими, только если они действительно возникнут.","We'll cross that bridge when we come to it.","Будем решать эту проблему, когда она возникнет."],["cry over spilled milk","горевать о непоправимом","Когда человек продолжает сожалеть о необратимой ошибке или потере и вы напоминаете, что прошлое уже не изменить.","There's no use crying over spilled milk.","Нет смысла горевать о том, чего уже не исправить."],["don't count your chickens before they hatch","цыплят по осени считают","Когда кто-то строит планы на ещё не полученные деньги, работу или другой результат и вы хотите предостеречь от преждевременной уверенности.","You haven't got the job yet. Don't count your chickens before they hatch.","Ты ещё не получил работу. Не радуйся раньше времени."],["down to earth","практичный, реалистичный, без высокомерия","Когда описываете человека, который остаётся рассудительным, доступным и неприхотливым, даже если добился успеха.","Despite her success, she's very down to earth.","Несмотря на успех, она остаётся практичной и простой в общении."],["draw the line","установить границу допустимого; сказать, что дальше нельзя","Когда хотите обозначить границу того, что готовы принять, и ясно сказать, какое поведение для вас уже недопустимо.","I draw the line at lying.","Ложь для меня недопустима."],["drop the ball","облажаться, допустить промах","Когда человек не выполнил важную обязанность, забыл о задаче или подвёл тех, кто на него рассчитывал. Разговорное выражение.","I dropped the ball on that project.","Я допустил серьёзный промах в том проекте."],["easier said than done","легче сказать, чем сделать","Когда вам дают совет или предлагают решение, которое звучит просто, но в реальности требует гораздо больше усилий.","Staying calm is easier said than done.","Сохранять спокойствие легче сказать, чем сделать."],["every cloud has a silver lining","нет худа без добра","Когда хотите ободрить человека после неприятности, напомнив, что даже в плохих обстоятельствах может найтись положительная сторона.","Every cloud has a silver lining, even after a setback.","Даже после неудачи можно найти что-то хорошее."],["feel like a million dollars","чувствовать себя великолепно","Когда после отдыха, выздоровления или удачного дня чувствуете себя исключительно бодрым и довольным.","After a good night's sleep, I feel like a million dollars.","После хорошего сна я чувствую себя великолепно."],["get a foot in the door","получить первый шанс","Когда обсуждаете первое небольшое достижение или знакомство, которое может открыть путь к работе, карьере или дальнейшим возможностям.","An internship can help you get a foot in the door.","Стажировка может дать первый шанс закрепиться в профессии."],["get something off one's chest","выговориться","Когда давно носите в себе тревогу, признание или обиду и хотите наконец рассказать об этом кому-то.","I need to get something off my chest.","Мне нужно выговориться."],["go back to the drawing board","начать разработку заново","Когда первая версия проекта или план не сработали и команде нужно заново продумать решение.","The design didn't work, so we went back to the drawing board.","Дизайн не сработал, и мы начали разработку заново."],["go with the flow","плыть по течению","Когда планы меняются и вы предпочитаете спокойно приспосабливаться к происходящему, а не пытаться всё контролировать.","On holiday, I prefer to go with the flow.","В отпуске я предпочитаю плыть по течению."],["have a lot on one's plate","иметь много дел","Когда объясняете, почему у вас сейчас мало свободного времени: накопилось много работы, обязательств или личных дел.","I've got a lot on my plate this week.","На этой неделе у меня очень много дел."],["hit the road","отправиться в путь","Когда пора начинать поездку, отправляться домой или уходить с места встречи. Разговорное выражение.","We should hit the road before sunrise.","Нам стоит отправиться в путь до рассвета."],["hold your horses","не торопись","Когда собеседник слишком спешит с решением или действием и вы просите его немного подождать. Неформально, иногда шутливо.","Hold your horses! We aren't ready yet.","Не торопись! Мы ещё не готовы."],["in a nutshell","в двух словах","Когда нужно кратко объяснить основную мысль сложной темы без подробностей.","In a nutshell, we need more time.","В двух словах, нам нужно больше времени."],["in full swing","в самом разгаре","Когда мероприятие, праздник или рабочий процесс уже начался и идёт особенно активно.","The festival was in full swing.","Фестиваль был в самом разгаре."],["in the blink of an eye","в мгновение ока","Когда событие произошло настолько быстро, что вы почти не успели его заметить.","The summer passed in the blink of an eye.","Лето пролетело в мгновение ока."],["jump the gun","начать действовать слишком рано; опередить события","Когда кто-то сделал объявление, начал действовать или принял решение до подходящего момента либо до получения всех сведений.","Don't jump the gun before we have all the facts.","Не торопись, пока у нас нет всех фактов."],["keep a low profile","не привлекать внимания","Когда хотите некоторое время оставаться незаметным, избегать публичности или лишнего внимания.","He decided to keep a low profile for a while.","Он решил некоторое время не привлекать внимания."],["keep your chin up","не падай духом","Когда человек переживает разочарование и вы хотите дружески поддержать его и помочь сохранить надежду.","Keep your chin up. You'll find another job.","Не падай духом. Ты найдёшь другую работу."],["learn the ropes","освоить азы","Когда начинаете новую работу, игру или занятие и постепенно знакомитесь с основными правилами и порядком действий.","It took me a week to learn the ropes.","Мне понадобилась неделя, чтобы освоить азы."],["look before you leap","семь раз отмерь, один раз отрежь","Когда хотите посоветовать человеку заранее оценить последствия рискованного решения, покупки или важного поступка.","Look before you leap when signing a contract.","Хорошо подумай, прежде чем подписывать договор."],["make a long story short","короче говоря","Когда рассказываете длинную историю и хотите пропустить второстепенные подробности, перейдя сразу к итогу.","To make a long story short, we missed the train.","Короче говоря, мы опоздали на поезд."],["no pain, no gain","без труда нет результата","Когда говорите о тренировках, учёбе или другой цели, для которой нужны усилия и настойчивость. Не означает, что вред или боль обязательны.","Learning takes practice: no pain, no gain.","Учёба требует практики: без труда нет результата."],["on thin ice","в рискованном положении","Когда человек уже совершал ошибки и рискует потерять доверие, работу или другую важную возможность при следующем промахе.","You're on thin ice after another missed deadline.","После очередного срыва срока твоё положение стало шатким."],["open a can of worms","создать целый клубок проблем","Когда обсуждение или решение может вскрыть целый ряд дополнительных, трудноразрешимых проблем.","That decision opened a can of worms.","Это решение породило целый клубок проблем."],["over the moon","вне себя от радости","Когда человек исключительно рад хорошей новости, удаче или исполнению желания. Особенно распространено в британском английском.","He was over the moon about the news.","Он был вне себя от радости от этой новости."],["pass the buck","перекладывать ответственность","Когда кто-то пытается переложить ответственность за решение или ошибку на другого вместо того, чтобы ответить за неё самому.","Stop passing the buck and solve the problem.","Перестань перекладывать ответственность и реши проблему."],["pull yourself together","возьми себя в руки","Когда человек сильно разволновался и вы призываете его восстановить самообладание. В чувствительной ситуации может прозвучать резко.","Take a deep breath and pull yourself together.","Глубоко вдохни и возьми себя в руки."],["rock the boat","нарушать спокойствие","Когда кто-то своими действиями нарушает привычный порядок, создаёт напряжение или бросает вызов сложившимся правилам.","Nobody wanted to rock the boat.","Никто не хотел нарушать сложившееся спокойствие."],["save for a rainy day","откладывать на чёрный день","Когда обсуждаете привычку откладывать деньги на непредвиденные расходы или возможные финансовые трудности в будущем.","I try to save a little for a rainy day.","Я стараюсь немного откладывать на чёрный день."],["speak of the devil","лёгок на помине","Когда человек неожиданно появляется сразу после того, как о нём говорили. Шутливо; не обязательно подразумевает что-то плохое.","Speak of the devil! We were just talking about you.","Лёгок на помине! Мы как раз о тебе говорили."],["take a rain check","отклонить приглашение сейчас, предложив встретиться позже","Когда не можете принять приглашение сейчас, но хотели бы вернуться к нему в другой раз. Особенно распространено в американском английском.","Can I take a rain check on dinner?","Можно поужинать в другой раз?"],["tip of the iceberg","верхушка айсберга","Когда обнаруженный факт, жалоба или проблема кажутся лишь маленькой видимой частью гораздо более серьёзной ситуации.","These complaints are just the tip of the iceberg.","Эти жалобы — лишь верхушка айсберга."],["when pigs fly","когда рак на горе свистнет","Когда в шутку подчёркиваете, что какое-то обещание или событие практически наверняка никогда не осуществится.","He'll clean his room when pigs fly.","Он уберёт комнату, когда рак на горе свистнет."]];

const idiomFavoriteKey='dalia-english-idiom-favorites-v1',idiomKeys=new Set(englishIdioms.map(q=>q[0]));let idiomFavorites=new Set();try{let saved=JSON.parse(localStorage.getItem(idiomFavoriteKey)||'[]');if(Array.isArray(saved))idiomFavorites=new Set(saved.filter(x=>idiomKeys.has(x)))}catch{}
let idiomIndex=Math.floor(Math.random()*englishIdioms.length),idiomCatalogOpen=false,idiomFavoritesOnly=false,idiomLimit=12,idiomMeaningOpen=false;
function nextIdiomIndex(previous){let n=Math.floor(Math.random()*(englishIdioms.length-1));return n>=previous?n+1:n}
function syncIdiomMeaning(){ $('quote-meaning-text').classList.toggle('hidden',!idiomMeaningOpen);$('quote-meaning-toggle').setAttribute('aria-expanded',String(idiomMeaningOpen))}
function renderIdiom(){let q=englishIdioms[idiomIndex];$('quote-cn').textContent=q[0];$('quote-ru').textContent=q[1];$('idiom-meaning').textContent=q[2];let fav=idiomFavorites.has(q[0]);$('quote-fav').textContent=fav?'♥ Сохранено':'♡ Сохранить';$('quote-fav').setAttribute('aria-pressed',String(fav));syncIdiomMeaning()}
function selectIdiom(i,scroll=false){stopSpeech();idiomIndex=i;idiomMeaningOpen=false;renderIdiom();if(scroll)$('wisdom-feature').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
function filterIdioms(term,favoritesOnly){return rankedSearch(englishIdioms.filter(q=>!favoritesOnly||idiomFavorites.has(q[0])),term,'idiom')}
function renderIdiomCatalog(){if(!idiomCatalogOpen)return;let result=filterIdioms($('quote-search').value,idiomFavoritesOnly),items=result.items,grid=$('quote-grid');$('quote-search-note').textContent=result.approximate?'Возможно, ты имел в виду эти выражения.':'';$('quote-search-note').classList.toggle('hidden',!result.approximate);grid.replaceChildren();$('quote-more').classList.toggle('hidden',items.length<=idiomLimit);if(!items.length){grid.append(el('div','empty',idiomFavoritesOnly?'Нет сохранённых выражений по этому запросу.':'Ничего не найдено. Попробуй другой запрос.'));return}for(let q of items.slice(0,idiomLimit)){let card=btn('','quote-small',()=>selectIdiom(englishIdioms.indexOf(q),true));card.setAttribute('aria-label','Открыть выражение: '+q[0]);card.append(el('small','',idiomFavorites.has(q[0])?'♥ · Выражение':'Выражение'),el('h3','',q[0]),el('p','',q[1]));grid.append(card)}}
function initIdioms(){ $('quote-speak').onclick=()=>speak(englishIdioms[idiomIndex][0]);$('quote-next').onclick=()=>selectIdiom(nextIdiomIndex(idiomIndex));$('quote-fav').onclick=()=>{let q=englishIdioms[idiomIndex][0],next=new Set(idiomFavorites);next.has(q)?next.delete(q):next.add(q);try{localStorage.setItem(idiomFavoriteKey,JSON.stringify([...next]))}catch{speechNotice('Не удалось сохранить выражение.');return}idiomFavorites=next;renderIdiom();renderIdiomCatalog()};$('quote-meaning-toggle').onclick=()=>{idiomMeaningOpen=!idiomMeaningOpen;syncIdiomMeaning()};$('quote-catalog-toggle').onclick=()=>{idiomCatalogOpen=!idiomCatalogOpen;$('quote-catalog-toggle').setAttribute('aria-expanded',String(idiomCatalogOpen));$('quote-catalog-body').classList.toggle('hidden',!idiomCatalogOpen);$('quote-catalog-toggle').querySelector('.wisdom-catalog-icon').textContent=idiomCatalogOpen?'−':'＋';renderIdiomCatalog()};initSearchInput('quote-search','quote-search-clear',()=>{idiomLimit=12;renderIdiomCatalog()});$('quote-filter-fav').onclick=()=>{idiomFavoritesOnly=!idiomFavoritesOnly;idiomLimit=12;$('quote-filter-fav').setAttribute('aria-pressed',String(idiomFavoritesOnly));$('quote-filter-fav').textContent=idiomFavoritesOnly?'♥ Избранные':'♡ Избранные';renderIdiomCatalog()};$('quote-more').onclick=()=>{idiomLimit+=12;renderIdiomCatalog()};renderIdiom()}

counts();render();initIdioms();initEnglishVoice();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){counts();if(collection)renderCollectionDrawer()}});enableEnglishAnalytics();if(typeof navigator!=='undefined'&&'serviceWorker' in navigator&&typeof location!=='undefined'&&/^https?:$/.test(location.protocol)){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'}).catch(()=>{}))}
